window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-385118861063be6e"]={"versions": [{"id": "FIG-385118861063be6e", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- bzw. Prozessdiagramm nach der AUTOSAR-Methodologie (SPEM-basiertes Prozessmodell). Das Diagramm beschreibt den methodischen Teilschritt „Define Frames“ im Rahmen des System- und Kommunikationsdesigns der AUTOSAR Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Rolle:</p>\n<ul class=\"fig-list\">\n<li><code>System Engineer</code> (Kardinalität 1): Ausführende Prozessrolle (Verknüpfung «performs»).</li>\n</ul>\n<p class=\"fig-p\">Aktivität:</p>\n<ul class=\"fig-list\">\n<li><code>Define Frames</code>: Zentrale Entwurfsaktivität zur Definition von Kommunikationsrahmen.</li>\n</ul>\n<p class=\"fig-p\">Artefakte und Datenflüsse:</p>\n<ul class=\"fig-list\">\n<li><code>Network Layer</code> (Kardinalität 0..1): Eingangs-Artefakt («input») für die Aktivität.</li>\n<li><code>Interaction Layer</code> (Kardinalität 0..1): Eingangs-Artefakt («input») für die Aktivität.</li>\n<li><code>Data Link Layer</code> (Kardinalität 1): Ausgangs-Artefakt («output») der Aktivität.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der <code>System Engineer</code> führt die Entwurfsaktivität <code>Define Frames</code> aus.</li>\n<li>Als optionale Eingangsinformationen werden Spezifikationsdaten aus dem <code>Network Layer</code> (0..1) sowie dem <code>Interaction Layer</code> (0..1) herangezogen.</li>\n<li>Die Aktivität erzeugt verbindlich als Ergebnis (1) das Artefakt <code>Data Link Layer</code> («output»), in dem die Frames für die Datenübertragung spezifiziert sind.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Methodischer Ablaufschritt für das AUTOSAR-Systemdesign. Für Werkzeugketten und Autoren von Konfigurations-Generatoren bedeutet dies: Mindestens ein Schichtenmodell bzw. Beschreibungsfragmente aus Interaction Layer oder Network Layer dienen als Grundlage, um die Frame-Strukturen der Sicherungsschicht (Data Link Layer) vollständig abzuleiten.</p>"}, {"id": "FIG-f646ecd082e16ef2", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- bzw. Prozessdiagramm nach der AUTOSAR-Methodologie (SPEM-basiertes Prozessmodell). Das Diagramm beschreibt den methodischen Teilschritt „Define Frames“ im Rahmen des System- und Kommunikationsdesigns der AUTOSAR Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Rolle:</p>\n<ul class=\"fig-list\">\n<li><code>System Engineer</code> (Kardinalität 1): Ausführende Prozessrolle (Verknüpfung «performs»).</li>\n</ul>\n<p class=\"fig-p\">Aktivität:</p>\n<ul class=\"fig-list\">\n<li><code>Define Frames</code>: Zentrale Entwurfsaktivität zur Definition von Kommunikationsrahmen.</li>\n</ul>\n<p class=\"fig-p\">Artefakte und Datenflüsse:</p>\n<ul class=\"fig-list\">\n<li><code>Network Layer</code> (Kardinalität 0..1): Eingangs-Artefakt («input») für die Aktivität.</li>\n<li><code>Interaction Layer</code> (Kardinalität 0..1): Eingangs-Artefakt («input») für die Aktivität.</li>\n<li><code>Data Link Layer</code> (Kardinalität 1): Ausgangs-Artefakt («output») der Aktivität.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der <code>System Engineer</code> führt die Entwurfsaktivität <code>Define Frames</code> aus.</li>\n<li>Als optionale Eingangsinformationen werden Spezifikationsdaten aus dem <code>Network Layer</code> (0..1) sowie dem <code>Interaction Layer</code> (0..1) herangezogen.</li>\n<li>Die Aktivität erzeugt verbindlich als Ergebnis (1) das Artefakt <code>Data Link Layer</code> («output»), in dem die Frames für die Datenübertragung spezifiziert sind.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Methodischer Ablaufschritt für das AUTOSAR-Systemdesign. Für Werkzeugketten und Autoren von Konfigurations-Generatoren bedeutet dies: Mindestens ein Schichtenmodell bzw. Beschreibungsfragmente aus Interaction Layer oder Network Layer dienen als Grundlage, um die Frame-Strukturen der Sicherungsschicht (Data Link Layer) vollständig abzuleiten.</p>"}], "trans": [{"from": "FIG-385118861063be6e", "to": "FIG-f646ecd082e16ef2", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
